// --- Java: HikariCP (Spring Boot Default) ---
HikariConfig config = new HikariConfig();
config.setJdbcUrl("jdbc:postgresql://db:5432/mydb");
config.setUsername("user");
config.setPassword("pass");
// CRITICAL: Pool size should be surprisingly small! (core_count * 2) + disks
config.setMaximumPoolSize(10);
// Prevent stale connections being kept alive forever
config.setMaxLifetime(1800000); // 30 mins
HikariDataSource ds = new HikariDataSource(config);

# --- Python: SQLAlchemy ---
from sqlalchemy import create_engine
# queue_pool is default. pool_size=10, max_overflow=5 means up to 15 connections max.
engine = create_engine(
    "postgresql://user:pass@db:5432/mydb",
    pool_size=10,
    max_overflow=5,
    pool_timeout=30,
    pool_pre_ping=True  # Pings the DB before checking out connection (prevents stale disconnects)
)
